VALUES
  (10,'Counter-Strike','Action','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/10/header.jpg?t=1745368572',NULL,'Play the world''s number 1 online action game. Engage in an incredibly realistic brand of terrorist warfare in this wildly popular team-based game. Ally with teammates to complete strategic missions. Take out enemy sites. Rescue hostages. Your role affects your team''s success. Your team''s success affects your role.','8,19€','1 Nov, 2000',88,'["Multi-player"]',unixepoch()),
  (80,'Counter-Strike: Condition Zero','Action','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/80/header.jpg?t=1745368574',NULL,'With its extensive Tour of Duty campaign, a near-limitless number of skirmish modes, updates and new content for Counter-Strike''s award-winning multiplayer game play, plus over 12 bonus single player missions, Counter-Strike: Condition Zero is a tremendous offering of single and multiplayer content.','8,19€','1 Mar, 2004',65,'["Multi-player"]',unixepoch()),
  (620,'Portal 2','Action','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/620/header.jpg?t=1745363004','https://video.akamai.steamstatic.com/store_trailers/620/3746/0f4bee66d490b637707ac4fca3e850f2cc2d3b2a/1750108721/hls_264_master.m3u8?t=1682715616','The &quot;Perpetual Testing Initiative&quot; has been expanded to allow you to design co-op puzzles for you and your friends!','9,75€','18 Apr, 2011',95,'["Multi-player","Co-op","Online Co-op","Shared/Split Screen Co-op"]',unixepoch()),
