       s.short_description,s.price,s.release_date,s.metacritic,
       i.minutes / 60.0,i.started,i.finished,'76561198049961191',unixepoch()
  FROM imported i JOIN steam_apps s ON s.appid=i.appid
  JOIN groups gr ON gr.slug='amadeus-solo-games'
  JOIN workspace_settings w ON w.group_id=gr.id AND w.mode='personal'
 WHERE NOT EXISTS (
   SELECT 1 FROM games existing
    WHERE existing.group_id=gr.id AND existing.steam_appid=i.appid
 );

